func TestLookupExtractionFullReportParity(t *testing.T) {
	for _, w := range transferParityWitnesses {
		t.Run(w.query, func(t *testing.T) {
			got, err := Analyze(QueryDocument{Text: w.query})
			if err != nil {
				t.Fatal(err)
			}
			var want Result
			if err := json.Unmarshal([]byte(w.result), &want); err != nil {
				t.Fatal(err)
			}
			if !reflect.DeepEqual(got, &want) {
				t.Errorf("Result changed: got %#v", got)
			}
			source, err := AnalyzeWithSourceUniverse(QueryDocument{Text: w.query}, SourceUniverse{Fields: []string{"host", "_time", "user", "src", "a", "b", "key"}})
			if err != nil {
				t.Fatal(err)
			}
			var wantSource SourceAnalysis
			if err := json.Unmarshal([]byte(w.source), &wantSource); err != nil {
				t.Fatal(err)
			}
			if !reflect.DeepEqual(source, &wantSource) {
				t.Errorf("SourceAnalysis changed: got %#v", source)
			}
		})
	}
}

func TestLocatedTransferEquivalence(t *testing.T) {
	// Reuse the exact field-flow witnesses' bytes and source refinement. The
	// second route invokes located operations without any generated contexts.
	for _, query := range []string{
		`search src=1 | eval a=src, b=a+1 | table b`,
		`search host=x _time=1 | table host _time | fields host | where _time>0`,
		`search host=x | fields -host | table host*`,
		`eval label=1 | table *`,
	} {
		t.Run(query, func(t *testing.T) {
			universe := SourceUniverse{Fields: []string{"host", "_time", "src"}}
			expected, err := AnalyzeWithSourceUniverse(QueryDocument{Text: query}, universe)
			if err != nil {
				t.Fatal(err)
			}
			r := newResult(expected.Result.Document)
			r.Stages = append([]Stage{}, expected.Result.Stages...)
			r.Scopes = append([]Scope{}, expected.Result.Scopes...)
			refinement := &sourceRefinement{names: []string{"_time", "host", "src"}, members: map[string]bool{"_time": true, "host": true, "src": true}, expansions: []FieldExpansion{}}
			trace := newRequirementTrace()
			s := &semanticStage{result: r, env: newEnvironmentWithRequirementTrace(trace), refinement: refinement}
			for i, stage := range r.Stages {
				s.stage = i
				r.Stages[i].SemanticComplete = true
				s.transitions = []Transition{}
				before := s.env.snapshot()
				operands := []locatedOperand{}
				refs := []Reference{}
				for _, ref := range expected.Result.References {
					if ref.StageID == stage.ID {
						operands = append(operands, locatedOperand{Name: ref.NormalizedName, Location: ref.Location, Resolution: ref.Resolution, Sound: true})
						refs = append(refs, ref)
					}
				}
				switch stage.Command {
				case "search":
					for _, op := range operands {
						s.readAt(op, "filter")
					}
				case "where":
					for _, op := range operands {
						s.readAt(op, "read")
					}
				case "eval":
					for j, ref := range refs {
						if ref.Role != "create" {
							continue
						}
						inputs := []string{}
						for k := j + 1; k < len(refs) && refs[k].Role != "create"; k++ {
							inputs = append(inputs, s.readAt(operands[k], "read"))
						}
						s.applyAssignment(operands[j], inputs, false, false)
					}
				case "fields", "table":
					mode := "include"
					if stage.Command == "table" {
						mode = "table"
					}
					if len(refs) > 0 && refs[0].Role == "remove" {
						mode = "exclude"
					}
					s.applyProjection(operands, mode, stage.Command == "fields" && mode == "include")
				default:
					t.Fatal("unhandled witness stage", stage.Command)
				}
				r.Lineage = append(r.Lineage, Lineage{StageID: stage.ID, ScopeID: stage.ScopeID, Before: before, After: s.env.snapshot(), Transitions: s.transitions})
			}
			finalizeReferences(r, refinement, trace)
			finalizeResult(r)
			requirements, err := projectRequirements(r.Document, trace)
			if err != nil {
				t.Fatal(err)
			}
			r.Requirements = requirements
			got := &SourceAnalysis{Result: r, Expansions: refinement.expansions}
			if !reflect.DeepEqual(got, expected) {
				a, _ := json.Marshal(got)
				b, _ := json.Marshal(expected)
				t.Fatalf("located differs\ngot %s\nwant %s", a, b)
			}
		})
	}
}

func TestPreparedProjectionPreservesEvidenceAndFinalizesIDs(t *testing.T) {
	doc := QueryDocument{Text: "alias source _time"}
	r := newResult(doc)
	r.Stages = []Stage{{ID: "stage-0", ScopeID: "scope-0", Command: "table", SemanticComplete: true}}
	s := &semanticStage{result: r, env: newEnvironment()}
	op := func(name string, start, end int) locatedOperand {
		return locatedOperand{Name: name, Location: newSourceIndex(doc.Text).location(start, end), Resolution: "exact", Sound: true}
	}
	sourceID := s.readAt(op("source", 6, 12), "read")
	aliasID := s.createAt(op("alias", 0, 5), "output", "create", []string{sourceID}, true)
	internalID := s.readAt(op("_time", 13, 18), "read")
	source := s.env.fields["source"]
	alias := s.env.fields["alias"]
	internal := s.env.fields["_time"]
	prepared := []preparedSelection{{source, []string{sourceID}, true}, {alias, []string{aliasID}, true}, {internal, nil, false}, {source, []string{sourceID}, true}}
	refsBefore, _ := json.Marshal(r.References)
	s.env.remove("gone")
	s.env.remove("source")
	s.env.remove("alias") // A later clause cannot cause re-resolution.
	s.transitions = []Transition{}
	s.applyPreparedProjection(prepared, "table")
	refsAfter, _ := json.Marshal(r.References)
	if string(refsAfter) != string(refsBefore) {
		t.Fatal("prepared installation created or rewrote references")
	}
	for _, want := range []trackedField{source, alias, internal} {
		if !reflect.DeepEqual(s.env.fields[want.Name], want) {
			t.Fatalf("lost copied field evidence: %#v", s.env.fields)
		}
	}
	if !s.env.removed["gone"] || s.env.open || s.env.uncertain {
		t.Fatal("changed restriction/tombstone policy", s.env)
	}
	if len(s.transitions) != 3 || s.transitions[0].InputReferenceIDs[0] != sourceID || s.transitions[1].InputReferenceIDs[0] != aliasID || s.transitions[2].InputReferenceIDs[0] != sourceID {
		t.Fatal("wrong ordered project transitions", s.transitions)
	}
	// Neither input evidence nor transition arrays may alias the installed bindings.
	prepared[0].Field.OriginReferenceIDs[0] = "mutated"
	prepared[0].InputReferenceIDs[0] = "mutated"
	if s.env.fields["source"].OriginReferenceIDs[0] != sourceID || s.transitions[0].InputReferenceIDs[0] != sourceID {
		t.Fatal("installation retained mutable caller arrays")
	}
	r.Lineage = []Lineage{{After: s.env.snapshot(), Transitions: s.transitions}}
	finalizeReferences(r, nil, nil)
	if r.References[0].ID != "ref-0" || r.References[0].NormalizedName != "alias" || r.References[1].ID != "ref-1" {
		t.Fatal("bad final order", r.References)
	}
	if r.Lineage[0].Transitions[0].InputReferenceIDs[0] != "ref-1" || r.Lineage[0].Transitions[1].InputReferenceIDs[0] != "ref-0" {
		t.Fatal("prepared IDs not finalized", r.Lineage)
	}
	_ = internalID
}

func TestLookupExtractionMatchEvidence(t *testing.T) {
	for _, w := range transferParityWitnesses[:3] {
		r, err := Analyze(QueryDocument{Text: w.query})
		if err != nil {
			t.Fatal(err)
		}
		stage := r.Stages[len(r.Stages)-1]
		matches := []Reference{}
		outputs := []Reference{}
		for _, ref := range r.References {
			if ref.StageID != stage.ID || ref.Kind != "field" {
				continue
			}
			if ref.Role == "read" {
				matches = append(matches, ref)
			}
			if ref.Role == "output" {
				outputs = append(outputs, ref)
			}
		}
		if len(matches) != 1 || matches[0].Binding != "source" || !reflect.DeepEqual(matches[0].OriginReferenceIDs, []string{"ref-0"}) {
			t.Fatal("local match repeated or changed provenance", matches)
		}
		if len(outputs) != 2 || outputs[0].Location.Start.Offset >= outputs[1].Location.Start.Offset {
			t.Fatal("output order changed", outputs)
		}
		for _, tr := range r.Lineage[len(r.Lineage)-1].Transitions {
			if !reflect.DeepEqual(tr.InputReferenceIDs, []string{matches[0].ID}) {
				t.Fatal("output lost prepared match", tr)
			}
		}
	}
}

func TestLocatedTransferExactNullRemovesWithoutReadOrCreation(t *testing.T) {
	doc := QueryDocument{Text: "field null() field"}
	r := newResult(doc)
	r.Stages = []Stage{{ID: "stage-0", Command: "eval", SemanticComplete: true}}
	s := &semanticStage{result: r, env: newEnvironment(), transitions: []Transition{}}
	target := locatedOperand{Name: "field", Location: newSourceIndex(doc.Text).location(0, 5), Resolution: "exact", Sound: true}
	s.env.install("field", []string{}, false)
	s.applyAssignment(target, nil, false, true)
	if len(r.References) != 1 || r.References[0].Role != "remove" || r.References[0].Binding != "not_applicable" || len(r.References[0].OriginReferenceIDs) != 0 {
		t.Fatal("null fabricated a target obligation or creation", r.References)
	}
	if _, known := s.env.fields["field"]; known || !s.env.removed["field"] {
		t.Fatal("null did not preserve canonical tombstone", s.env)
	}
	want := []Transition{{Operation: "remove", Output: "field", InputReferenceIDs: []string{}, OutputReferenceID: r.References[0].ID}}
	if !reflect.DeepEqual(s.transitions, want) {
		t.Fatal("null changed removal evidence", s.transitions)
	}
	target.Location = newSourceIndex(doc.Text).location(13, 18)
	s.readAt(target, "read")
	if r.References[1].Binding != "unavailable" || r.Diagnostics[0].Code != CodeUnavailableField {
		t.Fatal("later read resurrected removed target", r)
	}
}
